;ArC6/ZJ;;AqC9/ZE;EACE,aAAA;ArCigaJ;;AqClgaE;EACE,aAAA;ArCqgaJ;;AqCtgaE;EACE,aAAA;ArCygaJ;;AqC1gaE;EACE,aAAA;ArC6gaJ;;AqC9gaE;EACE,aAAA;ArCihaJ;;AqClhaE;EACE,aAAA;ArCqhaJ;;AqCthaE;EACE,aAAA;ArCyhaJ;;AqC1haE;EACE,aAAA;ArC6haJ;;AqC9haE;EACE,aAAA;ArCiiaJ;;AqCliaE;EACE,aAAA;ArCqiaJ;;AqCtiaE;EACE,aAAA;ArCyiaJ;;AqC1iaE;EACE,aAAA;ArC6iaJ;;AqC9iaE;EACE,aAAA;ArCijaJ;;AqCljaE;EACE,aAAA;ArCqjaJ;;AqCtjaE;EACE,aAAA;ArCyjaJ;;AqC1jaE;EACE,aAAA;ArC6jaJ;;AqC9jaE;EACE,aAAA;ArCikaJ;;AqClkaE;EACE,aAAA;ArCqkaJ;;AqCtkaE;EACE,aAAA;ArCykaJ;;AqC1kaE;EACE,aAAA;ArC6kaJ;;AqC9kaE;EACE,aAAA;ArCilaJ;;AqCllaE;EACE,aAAA;ArCqlaJ;;AqCtlaE;EACE,aAAA;ArCylaJ;;AqC1laE;EACE,aAAA;ArC6laJ;;AqC9laE;EACE,aAAA;ArCimaJ;;AqClmaE;EACE,aAAA;ArCqmaJ;;AqCtmaE;EACE,aAAA;ArCymaJ;;AqC1maE;EACE,aAAA;ArC6maJ;;AqC9maE;EACE,aAAA;ArCinaJ;;AqClnaE;EACE,aAAA;ArCqnaJ;;AqCtnaE;EACE,aAAA;ArCynaJ;;AqC1naE;EACE,aAAA;ArC6naJ;;AqC9naE;EACE,aAAA;ArCioaJ;;AqCloaE;EACE,aAAA;ArCqoaJ;;AsCpqaA;;;;EAAA;AASA;EACE,0CAAA;EACA,0DAAA;EAEA,8EAAA;EACA,mDAAA;AtCkqaF;;AsC9paE;EACE,kCAAA;EACA,kBAAA;EACA,gBAAA;EACA,mBH6BqB;EG5BrB,oEAAA;AtCiqaJ;AsC7paA;EACE,qCAAA;EACA,eAAA;AtC+paF;;AsC5paA;EACE,qCAAA;AtC+paF;;AsC5paA;EACE,eAAA;AtC+paF","file":"style.css","sourcesContent":["@charset \"UTF-8\";\n/*!------------------------------------------------------------------\n[MAIN STYLESHEET]\n\nPROJECT:\tThomson\nVERSION:\t1.0\n-------------------------------------------------------------------*/\n/*------------------------------------------------------------------\n[TABLE OF CONTENTS]\n-------------------------------------------------------------------*/\n@import url(\"https://fonts.googleapis.com/css?family=Lato:400,600,700|Work+Sans:400,700,800\");\nhtml {\n  overflow-x: hidden;\n}\n\nbody {\n  font-family: \"Lato\", sans-serif;\n  -webkit-font-smoothing: antialiased;\n  font-size: 16px;\n  font-weight: 400;\n  letter-spacing: 0.166667px;\n  line-height: 1.7em;\n  color: #818385;\n}\n\np {\n  color: #818385;\n}\n\nh1, .h1, h2, .h2, h3, .h3, h4, .h4, h5, .h5, h6, .h6 {\n  font-family: \"Work Sans\", sans-serif;\n  color: #000;\n  font-weight: 600;\n}\n\nh1, .h1 {\n  font-size: 45px;\n  text-transform: none;\n}\n\nh2, .h2 {\n  font-size: 42px;\n  line-height: 52px;\n}\n\nh3, .h3 {\n  font-size: 24px;\n  line-height: 34px;\n}\n\nh4, .h4 {\n  font-size: 20px;\n  line-height: 30px;\n}\n\nh5, .h5 {\n  font-size: 16px;\n  line-height: 26px;\n}\n\nh6, .h6 {\n  font-size: 14px;\n}\n\n.text-sm {\n  font-size: 14px;\n}\n\n.section {\n  padding: 120px 0px;\n}\n\n.section-sm {\n  padding: 60px 0px;\n}\n\n.btn {\n  padding: 18px 38px;\n  border: 2px solid transparent;\n  text-transform: uppercase;\n  border-radius: 0px;\n  font-size: 14px;\n  line-height: 14px;\n  font-weight: 600;\n  box-shadow: rgb(153, 153, 153) 0px 0px 0px 0px;\n}\n.btn:focus {\n  outline: 0px;\n  border: 0px;\n  box-shadow: none;\n}\n\n.btn-main {\n  background: #f44336;\n  color: #fff;\n}\n.btn-main:hover {\n  color: #fff !important;\n  background: #000;\n}\n\n.btn-black {\n  background: #000;\n  color: #fff;\n}\n.btn-black:hover {\n  background: #f44336;\n  color: #fff;\n}\n\n.btn-white {\n  background: #fff;\n  color: #000;\n  border-color: #fff;\n}\n.btn-white:hover {\n  background: transparent;\n  color: #fff;\n}\n\na {\n  color: #000;\n  -webkit-transition: all 0.25s ease;\n  -moz-transition: all 0.25s ease;\n  -ms-transition: all 0.25s ease;\n  -o-transition: all 0.25s ease;\n  transition: all 0.25s ease;\n}\na:hover {\n  color: #f44336;\n  text-decoration: none;\n  outline: none;\n}\n\n.bg-primary {\n  background: #f44336 !important;\n}\n\n.bg-secondary {\n  background: #f7f7f7 !important;\n}\n\n.bg-extra {\n  background: #e8eefb !important;\n}\n\n.text-color {\n  color: #f44336;\n}\n\n.page-title h1 {\n  position: relative;\n  padding-bottom: 30px;\n}\n.page-title h1:after {\n  position: absolute;\n  content: \"\";\n  left: 50%;\n  bottom: 0px;\n  width: 40px;\n  height: 2px;\n  margin-left: -25px;\n  background: #f44336;\n}\n\n@media (max-width: 575px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n@media (max-width: 400px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n/* ===================================\n   Language Switcher\n   =================================== */\n.language-switcher-container {\n  align-content: center;\n}\n\n.language-switcher .lang-toggle {\n  display: inline-flex;\n  position: relative;\n  background: rgba(255, 255, 255, 0.1);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  border-radius: 50px;\n  padding: 3px; /* reduced from 4px */\n  overflow: hidden;\n  align-items: center; /* vertically center buttons */\n  box-sizing: border-box;\n}\n.language-switcher .lang-btn {\n  position: relative;\n  z-index: 2;\n  background: transparent;\n  border: none;\n  color: rgba(132, 132, 132, 0.7);\n  font-size: 10px; /* reduced from 12px */\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.3px; /* reduced from 0.5px */\n  padding: 4px 12px; /* reduced from 6px 16px */\n  border-radius: 36px; /* slightly smaller */\n  cursor: pointer;\n  transition: color 0.3s ease;\n  white-space: nowrap;\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.language-switcher .lang-btn:hover {\n  color: #000; /* darker on hover */\n}\n.language-switcher .lang-btn.active {\n  color: #fff !important; /* white text on red slider - high contrast */\n}\n.language-switcher .lang-btn .lang-text {\n  display: inline-block;\n  transition: transform 0.2s ease, opacity 0.2s ease;\n}\n.language-switcher .lang-slider {\n  position: absolute;\n  top: 3px; /* matches toggle padding */\n  left: 3px; /* matches toggle padding */\n  height: calc(100% - 6px); /* matches toggle padding * 2 */\n  background: #f44336 !important; /* explicit red - $primary-color */\n  border-radius: 36px; /* matches button radius */\n  box-shadow: 0 2px 6px rgba(244, 67, 54, 0.5);\n  transition: transform 0.4s cubic-bezier(0.34, 1.56,